mapper.select:
SELECT ${sqlMap.column.toSql()}
FROM ${sqlMap.table.toSql()}

    ${sqlMap.where.toSql()}


        AND (${sqlMap.where.sqlSegment})


        AND a.record_name LIKE concat('%', #{recordName}, '%')


        AND a.warning_id = #{warningId}


        AND a.handler LIKE concat('%', #{handler}, '%')


        AND a.handle_status = #{handleStatus}


        AND a.alarm_time BETWEEN #{beginAlarmTime} AND #{endAlarmTime}


        AND a.handle_time BETWEEN #{beginHandleTime} AND #{endHandleTime}


ORDER BY ${sqlMap.order.toSql()}
